customCSS:
/* ============================================================
   Ders 9 -- application dugumu > Style > Custom CSS
   ------------------------------------------------------------
   Kabuk Bootstrap 4 + SB Admin 2, form kismi formio 4.8.1.
   Yani hazir bir sablonu eziyoruz; bircok yerde !important
   gerekiyor.

   Alan hedeflemenin puf noktasi: formio her bileseni
   .formio-component-<key> sinifiyla isaretliyor. Bizim dosya
   alanimizin key'i "belgeler" oldugu icin
   .formio-component-belgeler ile SADECE o alani hedefleyebiliyoruz.
   ============================================================ */

:root {
  --kurumsal:      #0b3d5c;
  --kurumsal-acik: #12628f;
  --vurgu:         #00a3a1;
  --zemin:         #f4f7f9;
}

/* ---------- 1. Ust bant ---------- */

nav.navbar {
  background: var(--kurumsal) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, .18);
}

/* Marka metni "<Uygulama adi> |" seklinde geliyor -- sondaki ayrac
   asagida gizlenen logo icin. Logoyu gizleyince ayrac bosta kaliyor.
   CSS bir metin dugumunun PARCASINI silemez; tumunu gizleyip ::after
   ile yeniden yazmak gerekiyor. Ayni cozumu alt bantta da kullaniyoruz. */
nav.navbar .navbar-brand {
  font-size: 0 !important;
}

nav.navbar .navbar-brand:after {
  content: "Sartname Zinciri";
  color: #fff;
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: .3px;
}

nav.navbar #sidebarToggle,
nav.navbar .nav-link {
  color: rgba(255, 255, 255, .85) !important;
}

/* "powered by aXet.flows" logosu ust bantta bir <img>.
   Kaldirmanin yolu yok, gizlemek var. */
#poweredByDeptapps {
  display: none !important;
}

/* ---------- 2. Yan menu ---------- */

ul.sidebar {
  background: #fff !important;
  border-right: 1px solid #dfe6ec;
}

ul.sidebar .nav-link {
  color: #2c3e50 !important;
  border-left: 3px solid transparent;
  border-radius: 0;
}

ul.sidebar .nav-item.active .nav-link,
ul.sidebar .nav-link:hover {
  background: var(--zemin) !important;
  border-left-color: var(--vurgu);
  color: var(--kurumsal) !important;
}

/* ---------- 3. Icerik alani ---------- */

body#page-top {
  background: var(--zemin);
}

.formio-component-form {
  background: #fff;
  border: 1px solid #e3e9ee;
  border-radius: 10px;
  padding: 28px 32px;
  max-width: 900px;
  margin: 24px auto;
}

.col-form-label {
  font-weight: 600;
  color: var(--kurumsal);
  font-size: 1.05rem;
}

/* Zorunlu alan yildizi Bootstrap'ta zor secilir; belirginlestir */
.field-required:after {
  color: #d64545 !important;
  font-size: 1.1em;
}

/* ---------- 4. Dosya birakma alani ---------- */
/* Sadece "belgeler" alanini hedefliyoruz. */

.formio-component-belgeler .fileSelector {
  border: 2px dashed #b6c6d3 !important;
  border-radius: 10px;
  background: #fbfdfe;
  padding: 34px 16px !important;
  text-align: center;
  color: #5b7285;
  font-size: 1.02rem;
  transition: border-color .15s, background .15s;
}

.formio-component-belgeler .fileSelector:hover {
  border-color: var(--vurgu) !important;
  background: #f2fbfb;
}

.formio-component-belgeler .fileSelector .fa-cloud-upload {
  display: block;
  font-size: 2.2rem;
  color: var(--vurgu);
  margin-bottom: 10px;
}

.formio-component-belgeler .fileSelector a.browse {
  color: var(--kurumsal-acik);
  font-weight: 600;
  text-decoration: underline;
}

/* ---------- 5. Yuklenen dosya listesi ---------- */

.formio-component-belgeler ul.list-group {
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 12px;
}

.formio-component-belgeler .list-group-header {
  background: var(--kurumsal) !important;
  color: #fff !important;
  font-weight: 600;
  text-transform: uppercase;
  font-size: .78rem;
  letter-spacing: .6px;
}

.formio-component-belgeler li.list-group-item {
  border-color: #e8eef3;
}

.formio-component-belgeler li.list-group-item:hover {
  background: #f7fbfc;
}

/* Silme carpisi -- varsayilan halde duz siyah metin gibi duruyor */
.formio-component-belgeler li.list-group-item .col-md-1 i {
  color: #b6c6d3;
  cursor: pointer;
}

.formio-component-belgeler li.list-group-item .col-md-1 i:hover {
  color: #d64545;
}

/* ---------- 6. Gonder dugmesi ---------- */

.formio-component-button button.btn-primary {
  background: var(--vurgu) !important;
  border-color: var(--vurgu) !important;
  padding: 11px 34px !important;
  font-weight: 600;
  font-size: 1.02rem;
  border-radius: 7px;
  box-shadow: 0 2px 6px rgba(0, 163, 161, .3);
}

.formio-component-button button.btn-primary:hover:not(:disabled) {
  background: #008a88 !important;
  border-color: #008a88 !important;
}

.formio-component-button button.btn-primary:disabled {
  background: #b9c6ce !important;
  border-color: #b9c6ce !important;
  box-shadow: none;
}

/* ---------- 7. Alt bant ---------- */
/* Telif satiri tek bir <span> icinde geliyor:
     "<Uygulama adi> Powered by aXet.flows (c) 2026 NTT Data..."
   Parcalayip sadece bir kismini silmek MUMKUN DEGIL. Ya tumunu
   gizlersin ya da gizleyip yerine ::after ile kendi metnini koyarsin.
   Asagida ikincisi yapiliyor. */

footer.sticky-footer {
  background: #fff;
  border-top: 1px solid #e3e9ee;
}

footer.sticky-footer .copyright span {
  display: none;
}

footer.sticky-footer .copyright:after {
  content: "Sartname Zinciri -- ic kullanim";
  color: #8a9aa8;
  font-size: .86rem;
}

func:
// Form ekinden gelen dosyalari tek bir metne cevirir.
//
// Formio'nun "base64" depolama modunda her dosya soyle gelir:
//   {
//     storage:      "base64",
//     name:         "01-toplanti.md",
//     originalName: "01-toplanti.md",
//     type:         "text/markdown",
//     size:         1234,
//     url:          "data:text/markdown;base64,IyBUb3BsYW50..."
//   }
//
// Icerik dosyanin KENDISINDE (url alaninda) tasiniyor -- diske hicbir sey
// yazilmiyor, ayri bir depolama servisi gerekmiyor. Bedeli: dosya
// tarayicidan sunucuya base64 olarak gidiyor, yani ~%33 sismis halde.

const veri = (msg.payload && msg.payload.data) || {};
const dosyalar = veri.belgeler;

if (!Array.isArray(dosyalar) || dosyalar.length === 0) {
  node.status({ fill: "red", shape: "ring", text: "dosya yok" });
  node.error("Form dosya eklenmeden gonderildi", msg);
  return null;
}

const NL = String.fromCharCode(10);
const parcalar = [];

for (const d of dosyalar) {
  const url = d.url || "";
  const virgul = url.indexOf(",");

  // "data:<mime>;base64,<icerik>" bicimini bekliyoruz. Baska bir depolama
  // modu secilirse (s3, url, azure) burada url yerine bir HTTP adresi
  // gelir ve bu kontrol devreye girer.
  if (virgul < 0 || url.indexOf("base64") < 0) {
    node.error("Dosya base64 degil, depolama modunu kontrol edin: " + (d.name || "?"), msg);
    return null;
  }

  const metin = Buffer.from(url.slice(virgul + 1), "base64").toString("utf8");
  parcalar.push("### DOSYA: " + (d.originalName || d.name) + NL + metin);
}

msg.dosyaSayisi = dosyalar.length;
msg.dosyaAdlari = dosyalar.map(d => d.originalName || d.name);
msg.payload = parcalar.join(NL + NL);

node.status({
  fill: "blue",
  shape: "dot",
  text: msg.dosyaSayisi + " dosya / " + msg.payload.length + " karakter"
});

return msg;

// Ajan cevabi { response: "..." } yapisinda gelir (outputSchema yoksa).
// Metni hem dosyaya yazmak hem sonraki adimlara tasimak icin ayiriyoruz.

msg.fsMetni = msg.payload.response || msg.payload;
msg.payload = msg.fsMetni;   // file dugumu METIN bekler
msg.filename = "/internal-storage-files/cikti/01-FS.md";

node.status({ fill: "green", shape: "dot", text: "FS yazildi" });
return msg;

// Bu dugum iki yoldan gecilir:
//   1. Ilk gelis  -> FS'ten gelir, msg.tur = 0
//   2. Geri donus -> Reviewer'dan gelir, msg.tur artmistir ve
//                    msg.bulgular doludur
//
// Ders 7'deki retry dongusunun aynisi: sayac msg uzerinde, ust sinir var.

msg.tur = (msg.tur || 0) + 1;

const NL = String.fromCharCode(10);   // kacis sorunu yasamamak icin
const fs = msg.fsMetni;
const oncekiTs = msg.tsMetni || "";
const bulgular = msg.bulgular || [];

let duzeltmeBolumu = "";
if (bulgular.length > 0) {
  const liste = bulgular
    .map(b => "- [" + (b.onem || "orta") + "] " + b.madde)
    .join(NL);

  // ONEMLI: onceki TS'in TAMAMINI geri gondermiyoruz.
  // Ilk denemede gonderdik ve platform gecidi zaman asimina ugradi
  // (OriginTimeout). Sadece bolum basliklarini gonderiyoruz; yapi
  // korunuyor ama girdi kucuk kaliyor.
  const basliklar = oncekiTs
    .split(NL)
    .filter(l => l.charAt(0) === "#")
    .join(NL);

  duzeltmeBolumu = [
    "",
    "BU BIR DUZELTME TURU (tur " + msg.tur + ").",
    "Asagidaki bulgulari giderecek sekilde belgeyi YENIDEN uret.",
    "",
    "BULGULAR:",
    liste,
    "",
    "ONCEKI BELGENIN YAPISI (sadece basliklar -- bu yapiyi koru):",
    "---",
    basliklar,
    "---",
    ""
  ].join(NL);
}

msg.payload = [
  "Asagidaki fonksiyonel sartnameden bir TEKNIK SARTNAME (TS) uret.",
  duzeltmeBolumu,
  "Kurallar:",
  "",
  "1. ABAP / SAP S4HANA hedefle.",
  "2. Kullanilacak tablolari ve alanlari acikca yaz.",
  "3. Program adi, tablo tipi, yapi adlarini naming convention'a uydur.",
  "4. Performans kisitini goz ardi etme.",
  "5. KISA TUT: en fazla 180 satir. Uzun belge uretme -- platform gecidi",
  "   uzun cevaplarda zaman asimina ugruyor.",
  "6. Ciktiyi Markdown olarak ver. Baslik yapisi:",
  "   # Teknik Sartname",
  "   ## 1. Genel Bakis",
  "   ## 2. Veri Kaynaklari",
  "   ## 3. Program Yapisi",
  "   ## 4. Algoritma",
  "   ## 5. Yetki ve Zamanlama",
  "   ## 6. Test Senaryolari",
  "",
  "FONKSIYONEL SARTNAME:",
  "---",
  fs,
  "---"
].join(NL);

node.status({ fill: "blue", shape: "dot", text: "TS uretiliyor (tur " + msg.tur + ")" });
return msg;

// Her tur ayri dosyaya yazilir: 02-TS-tur1.md, 02-TS-tur2.md ...
// Boylece "ikinci turda ne degisti?" sorusu somut olarak cevaplanabilir.

msg.tsMetni = msg.payload.response || msg.payload;
msg.payload = msg.tsMetni;
msg.filename = `/internal-storage-files/cikti/02-TS-tur${msg.tur}.md`;

node.status({ fill: "green", shape: "dot", text: `TS tur ${msg.tur} yazildi` });
return msg;

// Reviewer'in cevabi outputSchema ile YAPILANDIRILMIS gelir:
//   { onay: boolean, bulgular: [{madde, onem}], ozet: string }
// Bu yuzden switch dugumu metin icinde arama yapmak zorunda kalmaz.

msg.tsMetni = msg.payload.response || msg.payload;

msg.payload = `Asagidaki teknik sartnameyi bir SAP kidemli gelistiricisi
gozuyle incele.

Sorulacak sorular:
- Fonksiyonel sartnamedeki her kural teknik olarak karsilanmis mi?
- Tablo ve alan secimleri dogru mu?
- Performans kisiti dikkate alinmis mi?
- Gelistirici bu belgeyle kod yazmaya baslayabilir mi?

Eksik veya hatali bir sey bulursan onay verme; bulgulari maddeler halinde yaz.
EN FAZLA 5 BULGU yaz -- sadece gelistirmeyi engelleyecek kadar onemli
olanlari. Kucuk eksikleri gormezden gel.
Belge yeterliyse onay ver.

FONKSIYONEL SARTNAME:
---
${msg.fsMetni}
---

TEKNIK SARTNAME:
---
${msg.tsMetni}
---`;

node.status({ fill: "blue", shape: "dot", text: "inceleniyor..." });
return msg;

// Reviewer ciktisini oku ve karari msg'ye yaz.
// switch dugumu bundan sonra sadece msg.karar alanina bakar.

const r = msg.payload;           // outputSchema sayesinde nesne
const ENUST_TUR = 2;             // duzeltme turu ust siniri

msg.onay = r.onay === true;
msg.bulgular = r.bulgular || [];
msg.ozet = r.ozet || "";

if (msg.onay) {
  msg.karar = "gelistir";
  node.status({ fill: "green", shape: "dot", text: `onaylandi (tur ${msg.tur})` });
} else if (msg.tur < ENUST_TUR) {
  msg.karar = "duzelt";
  node.status({ fill: "yellow", shape: "ring",
                text: `duzeltme (${msg.bulgular.length} bulgu)` });
} else {
  msg.karar = "mudahale";
  node.status({ fill: "red", shape: "dot", text: "tur hakki bitti" });
}

return msg;

msg.payload = `Asagidaki teknik sartnameye gore ABAP kodunu yaz.

Kurallar:
1. Calisir, eksiksiz bir program yaz -- sozde kod degil.
2. Naming convention'a uy.
3. Kodu yorumla; her ana blogun ne yaptigini kisaca acikla.
4. Sadece kodu dondur, aciklama metni ekleme.

TEKNIK SARTNAME:
---
${msg.tsMetni}
---`;

node.status({ fill: "blue", shape: "dot", text: "kod yaziliyor..." });
return msg;

const kod = msg.payload.response || msg.payload;

msg.payload = kod;
msg.filename = "/internal-storage-files/cikti/03-kod.abap";

node.status({ fill: "green", shape: "dot", text: `kod yazildi (tur ${msg.tur})` });
return msg;

// Ust sinira ulasildi: zincir kendini toparlayamadi.
// Ders 7'nin "vazgec" dali ile ayni felsefe -- sessizce durma, iz birak.

const satirlar = [
  "# Insan mudahalesi gerekli",
  "",
  `Zincir ${msg.tur} turda onay alamadi.`,
  "",
  "## Reviewer ozeti",
  msg.ozet || "(ozet yok)",
  "",
  "## Kalan bulgular",
  ...(msg.bulgular || []).map(b => `- [${b.onem || "orta"}] ${b.madde}`),
  "",
  `Son teknik sartname: /internal-storage-files/cikti/02-TS-tur${msg.tur}.md`
];

msg.payload = satirlar.join("\n");
msg.filename = "/internal-storage-files/cikti/MUDAHALE-GEREKLI.md";

node.warn(["ZINCIR ONAY ALAMADI", msg.ozet]);
return msg;
